//! Minimal TOML reading/writing, just enough for jot's state files.
//!
//! The state files only ever contain top-level string/bool values, one `[vaults]`
//! table of string values, and one array-of-strings (`history`). Rather than pull in
//! a full TOML implementation we parse exactly that shape.

/// A parsed TOML document: a flat list of (section, key, value) with values kept as
/// the decoded string / bool / list they represent.
#[derive(Debug, Clone, PartialEq)]
pub enum Value {
    Str(String),
    Bool(bool),
    Array(Vec<String>),
}

impl Value {
    pub fn as_str(&self) -> Option<&str> {
        match self {
            Value::Str(s) => Some(s),
            _ => None,
        }
    }
    pub fn as_bool(&self) -> Option<bool> {
        match self {
            Value::Bool(b) => Some(*b),
            _ => None,
        }
    }
    pub fn as_array(&self) -> Option<&Vec<String>> {
        match self {
            Value::Array(v) => Some(v),
            _ => None,
        }
    }
}

/// An ordered map of entries belonging to one table.
#[derive(Debug, Default, Clone)]
pub struct Table {
    pub entries: Vec<(String, Value)>,
}

impl Table {
    pub fn get(&self, key: &str) -> Option<&Value> {
        self.entries.iter().find(|(k, _)| k == key).map(|(_, v)| v)
    }

    pub fn set(&mut self, key: &str, value: Value) {
        match self.entries.iter_mut().find(|(k, _)| k == key) {
            Some(slot) => slot.1 = value,
            None => self.entries.push((key.to_string(), value)),
        }
    }

    pub fn remove(&mut self, key: &str) -> Option<Value> {
        let idx = self.entries.iter().position(|(k, _)| k == key)?;
        Some(self.entries.remove(idx).1)
    }

    pub fn contains_key(&self, key: &str) -> bool {
        self.entries.iter().any(|(k, _)| k == key)
    }
}

/// A whole document: the root table plus named sub-tables, both order preserving.
#[derive(Debug, Default, Clone)]
pub struct Doc {
    pub root: Table,
    pub tables: Vec<(String, Table)>,
}

impl Doc {
    pub fn table(&self, name: &str) -> Option<&Table> {
        self.tables.iter().find(|(n, _)| n == name).map(|(_, t)| t)
    }

    pub fn table_mut(&mut self, name: &str) -> &mut Table {
        if let Some(idx) = self.tables.iter().position(|(n, _)| n == name) {
            return &mut self.tables[idx].1;
        }
        self.tables.push((name.to_string(), Table::default()));
        let last = self.tables.len() - 1;
        &mut self.tables[last].1
    }
}

/// Parse the subset of TOML jot writes. Returns `None` when the text is not
/// something we can make sense of at all.
pub fn parse(text: &str) -> Option<Doc> {
    let mut doc = Doc::default();
    let mut current: Option<String> = None;

    for raw in text.lines() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        if line.starts_with('[') {
            let name = line.strip_prefix('[')?.strip_suffix(']')?.trim().to_string();
            if name.is_empty() {
                return None;
            }
            doc.table_mut(&name);
            current = Some(name);
            continue;
        }
        let eq = line.find('=')?;
        let key = unquote_key(line[..eq].trim())?;
        let value = parse_value(line[eq + 1..].trim())?;
        match &current {
            None => doc.root.set(&key, value),
            Some(name) => doc.table_mut(name).set(&key, value),
        }
    }
    Some(doc)
}

fn unquote_key(raw: &str) -> Option<String> {
    if raw.is_empty() {
        return None;
    }
    if (raw.starts_with('"') && raw.ends_with('"') && raw.len() >= 2)
        || (raw.starts_with('\'') && raw.ends_with('\'') && raw.len() >= 2)
    {
        return Some(raw[1..raw.len() - 1].to_string());
    }
    if raw.chars().any(|c| c.is_whitespace() || c == '[' || c == ']') {
        return None;
    }
    Some(raw.to_string())
}

fn parse_value(raw: &str) -> Option<Value> {
    if raw == "true" {
        return Some(Value::Bool(true));
    }
    if raw == "false" {
        return Some(Value::Bool(false));
    }
    if let Some(rest) = raw.strip_prefix('[') {
        let inner = rest.strip_suffix(']')?.trim();
        let mut out = Vec::new();
        if !inner.is_empty() {
            for part in split_array(inner)? {
                out.push(scan_string(part.trim())?);
            }
        }
        return Some(Value::Array(out));
    }
    Some(Value::Str(scan_string(raw)?))
}

/// Split an array body on commas that are not inside quotes.
fn split_array(inner: &str) -> Option<Vec<String>> {
    let mut parts = Vec::new();
    let mut buf = String::new();
    let mut quote: Option<char> = None;
    let mut escaped = false;
    for c in inner.chars() {
        match quote {
            Some(q) => {
                buf.push(c);
                if escaped {
                    escaped = false;
                } else if q == '"' && c == '\\' {
                    escaped = true;
                } else if c == q {
                    quote = None;
                }
            }
            None => {
                if c == '"' || c == '\'' {
                    quote = Some(c);
                    buf.push(c);
                } else if c == ',' {
                    parts.push(std::mem::take(&mut buf));
                } else {
                    buf.push(c);
                }
            }
        }
    }
    if quote.is_some() {
        return None;
    }
    if !buf.trim().is_empty() {
        parts.push(buf);
    }
    Some(parts)
}

fn scan_string(raw: &str) -> Option<String> {
    let bytes: Vec<char> = raw.chars().collect();
    if bytes.len() < 2 {
        return None;
    }
    if bytes[0] == '\'' {
        if *bytes.last().unwrap() != '\'' {
            return None;
        }
        return Some(bytes[1..bytes.len() - 1].iter().collect());
    }
    if bytes[0] != '"' {
        return None;
    }
    if *bytes.last().unwrap() != '"' {
        return None;
    }
    let mut out = String::new();
    let mut i = 1;
    let end = bytes.len() - 1;
    while i < end {
        let c = bytes[i];
        if c != '\\' {
            out.push(c);
            i += 1;
            continue;
        }
        i += 1;
        if i >= end {
            return None;
        }
        match bytes[i] {
            'n' => out.push('\n'),
            't' => out.push('\t'),
            'r' => out.push('\r'),
            '"' => out.push('"'),
            '\\' => out.push('\\'),
            'b' => out.push('\u{8}'),
            'f' => out.push('\u{c}'),
            'u' | 'U' => {
                let width = if bytes[i] == 'u' { 4 } else { 8 };
                let mut n: u32 = 0;
                for _ in 0..width {
                    i += 1;
                    if i >= end {
                        return None;
                    }
                    n = n * 16 + bytes[i].to_digit(16)?;
                }
                out.push(char::from_u32(n)?);
            }
            other => {
                out.push('\\');
                out.push(other);
            }
        }
        i += 1;
    }
    Some(out)
}

/// Render a value the way jot's own writer does: literal single-quoted strings when
/// possible, basic double-quoted strings when the text would break a literal string.
pub fn render_value(value: &Value) -> String {
    match value {
        Value::Bool(b) => b.to_string(),
        Value::Str(s) => render_string(s),
        Value::Array(items) => {
            if items.is_empty() {
                "[]".to_string()
            } else {
                let parts: Vec<String> = items.iter().map(|s| render_string(s)).collect();
                format!("[{}]", parts.join(", "))
            }
        }
    }
}

/// A literal (single-quoted) TOML string cannot hold a single quote, a newline, or
/// other control characters; fall back to a basic string in those cases.
pub fn render_string(s: &str) -> String {
    let needs_basic = s
        .chars()
        .any(|c| c == '\'' || c.is_control() || c == '\u{7f}');
    if !needs_basic {
        return format!("'{}'", s);
    }
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\t' => out.push_str("\\t"),
            '\r' => out.push_str("\\r"),
            '\u{8}' => out.push_str("\\b"),
            '\u{c}' => out.push_str("\\f"),
            c if c.is_control() || c == '\u{7f}' => {
                out.push_str(&format!("\\u{:04X}", c as u32));
            }
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

/// Render a key: bare when it is a valid bare key, quoted otherwise.
pub fn render_key(key: &str) -> String {
    let bare = !key.is_empty()
        && key
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-');
    if bare {
        key.to_string()
    } else {
        render_string(key)
    }
}

