//! Command line parsing.
//!
//! The reference tool is built on a builder-style argument parser; this module
//! reproduces the surface we care about: subcommands with aliases, positional
//! arguments, one boolean flag, `-h`/`--help`, and the exact wording of the
//! parse errors it emits (always uncoloured, on stderr, exit status 2).

use crate::help_text as ht;

/// Placeholder inside the captured help text for the program name.
const BIN_PLACEHOLDER: &str = "{BIN}";

/// A positional argument declaration.
struct Positional {
    /// Display name, e.g. `vault name` (rendered as `<vault name>`).
    name: &'static str,
    required: bool,
}

/// A subcommand declaration.
struct Spec {
    name: &'static str,
    alias: &'static str,
    /// Verbatim help page; `{BIN}` is replaced with the program name.
    help: &'static str,
    /// Usage block shown in parse errors. `{BIN}` is replaced likewise.
    usage: &'static str,
    positionals: &'static [Positional],
    /// Whether `-l` is accepted.
    takes_l: bool,
}

const ROOT_USAGE: &str = "    {BIN} <SUBCOMMAND>";

const SPECS: &[Spec] = &[
    Spec {
        name: "vault",
        alias: "vl",
        help: ht::HELP_VAULT,
        usage: "    jt vault\n    jt vault -l\n    jt vault <vault name> <vault location>",
